cd C:/Users/Derek/Desktop/heretek-swarm && .venv/Scripts/python.exe -c "
import re, os
markers_used = set()
for root, dirs, files in os.walk('tests'):
    for f in files:
        if f.endswith('.py'):
            path = os.path.join(root, f)
            with open(path) as fh:
                for line in fh:
                    m = re.findall(r'@pytest\.mark\.(\w+)', line)
                    markers_used.update(m)
print('Markers used in test files:')
for m in sorted(markers_used):
    print(f'  {m}')
"

